"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface MarqueeProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Seconden voor één volledige ronde; hoger is trager. */
  duration?: number;
  /** De andere kant op. */
  reverse?: boolean;
  /** Van onder naar boven in plaats van zijwaarts. */
  vertical?: boolean;
  /** Stilstaan zolang de muis erboven hangt. */
  pauseOnHover?: boolean;
  /** Ruimte tussen de kinderen. */
  gap?: number;
  /** Zachte rand links en rechts, zodat de inhoud niet hard afgesneden lijkt. */
  fade?: boolean;
  /** Hoe vaak de rij herhaald wordt; meer bij weinig inhoud. */
  repeat?: number;
}

/**
 * Marquee — rij die eindeloos doorloopt. Pure CSS, dus geen dependency en
 * geen JavaScript per frame. De inhoud wordt herhaald, zodat de lus naadloos is.
 */
export const Marquee = React.forwardRef<HTMLDivElement, MarqueeProps>(function Marquee(
  {
    duration = 28,
    reverse,
    vertical,
    pauseOnHover = true,
    gap = 20,
    fade,
    repeat = 2,
    className,
    children,
    style,
    ...rest
  },
  ref
) {
  return (
    <div
      ref={ref}
      className={cn(
        "lui-marquee",
        vertical && "lui-marquee-vertical",
        fade && "lui-marquee-fade",
        pauseOnHover && "lui-marquee-pausable",
        className
      )}
      style={{
        ...style,
        ["--lui-marquee-duration" as string]: `${duration}s`,
        ["--lui-marquee-gap" as string]: `${gap}px`,
        ["--lui-marquee-direction" as string]: reverse ? "reverse" : "normal",
      }}
      {...rest}
    >
      {Array.from({ length: Math.max(repeat, 2) }, (_, index) => (
        <div className="lui-marquee-row" key={index} aria-hidden={index > 0 ? "true" : undefined}>
          {children}
        </div>
      ))}
    </div>
  );
});

/* ============================ Marquee ============================ */
.lui-marquee {
  --lui-marquee-duration: 28s;
  --lui-marquee-gap: 20px;
  --lui-marquee-direction: normal;
  display: flex; gap: var(--lui-marquee-gap);
  width: 100%; overflow: hidden;
}
.lui-marquee-row {
  display: flex; flex: none; align-items: center; gap: var(--lui-marquee-gap);
  min-width: max-content;
  animation: lui-marquee-x var(--lui-marquee-duration) linear infinite var(--lui-marquee-direction);
}

.lui-marquee-vertical { flex-direction: column; height: 100%; }
.lui-marquee-vertical .lui-marquee-row {
  flex-direction: column; min-width: 0; min-height: max-content;
  animation-name: lui-marquee-y;
}

.lui-marquee-pausable:hover .lui-marquee-row { animation-play-state: paused; }

.lui-marquee-fade {
  -webkit-mask-image: linear-gradient(to right, transparent, #000 8%, #000 92%, transparent);
  mask-image: linear-gradient(to right, transparent, #000 8%, #000 92%, transparent);
}
.lui-marquee-fade.lui-marquee-vertical {
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 8%, #000 92%, transparent);
  mask-image: linear-gradient(to bottom, transparent, #000 8%, #000 92%, transparent);
}

/* Eén rij plus de gap opschuiven: precies de breedte van de kopie ervoor. */
@keyframes lui-marquee-x {
  from { transform: translateX(0); }
  to { transform: translateX(calc(-100% - var(--lui-marquee-gap))); }
}
@keyframes lui-marquee-y {
  from { transform: translateY(0); }
  to { transform: translateY(calc(-100% - var(--lui-marquee-gap))); }
}

@media (prefers-reduced-motion: reduce) {
  .lui-marquee-row { animation: none; }
  .lui-marquee { overflow-x: auto; }
}
